----------------------------------------
-- TMP2: Home Loan / Mortgage (HL_) Count Features
----------------------------------------

MKR_LONGLIST_TMP2 AS (

SELECT  A.ID,
        ------------------------------------------------------------------------
        ------- KONUT KREDILERI ------------------------------------------------
        ------------------------------------------------------------------------
        -------Kullandirim Adetleri --------------------------------------------
        SUM(CASE WHEN CREDIT_TYPE_DRV = '300' THEN 1 ELSE 0 END) AS HL_CNT_EVER,
        SUM(CASE WHEN CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  30 THEN 1 ELSE 0 END) AS HL_CNT_30D,
        SUM(CASE WHEN CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN 1 ELSE 0 END) AS HL_CNT_90D,
        SUM(CASE WHEN CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN 1 ELSE 0 END) AS HL_CNT_182D,
        SUM(CASE WHEN CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN 1 ELSE 0 END) AS HL_CNT_183D365D,
        -------Acik Kredi Adetleri----------------------------------------------
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' THEN 1 ELSE 0 END) AS HL_OCNT_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN 1 ELSE 0 END) AS HL_OCNT_90D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN 1 ELSE 0 END) AS HL_OCNT_182D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN 1 ELSE 0 END) AS HL_OCNT_183D365D,
        -------Acik ve guncel odeme durumu 0 olan Kredi Adetleri ---------------
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND (CASE WHEN TRIM(ACCOUNT_PAYMENT_STATUS) IS NULL THEN -3 ELSE CASE UPPER(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) WHEN '0' THEN 0 WHEN '1' THEN 1 WHEN '2' THEN 2 WHEN '3' THEN 3 WHEN '4' THEN 4 WHEN '5' THEN 5 WHEN '6' THEN 6 WHEN '7' THEN 7 WHEN '8' THEN 8 WHEN '9' THEN 9 WHEN 'T' THEN 8 WHEN 'L' THEN 9 WHEN 'K' THEN 9 WHEN 'D' THEN -1 WHEN 'U' THEN -1 WHEN 'X' THEN -1 WHEN 'N' THEN -1 ELSE -2 END END) = 0 THEN 1 ELSE 0 END) AS HL_OCNT_CWPS0_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND (CASE WHEN TRIM(ACCOUNT_PAYMENT_STATUS) IS NULL THEN -3 ELSE CASE UPPER(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) WHEN '0' THEN 0 WHEN '1' THEN 1 WHEN '2' THEN 2 WHEN '3' THEN 3 WHEN '4' THEN 4 WHEN '5' THEN 5 WHEN '6' THEN 6 WHEN '7' THEN 7 WHEN '8' THEN 8 WHEN '9' THEN 9 WHEN 'T' THEN 8 WHEN 'L' THEN 9 WHEN 'K' THEN 9 WHEN 'D' THEN -1 WHEN 'U' THEN -1 WHEN 'X' THEN -1 WHEN 'N' THEN -1 ELSE -2 END END) = 0 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN 1 ELSE 0 END) AS HL_OCNT_CWPS0_90D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND (CASE WHEN TRIM(ACCOUNT_PAYMENT_STATUS) IS NULL THEN -3 ELSE CASE UPPER(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) WHEN '0' THEN 0 WHEN '1' THEN 1 WHEN '2' THEN 2 WHEN '3' THEN 3 WHEN '4' THEN 4 WHEN '5' THEN 5 WHEN '6' THEN 6 WHEN '7' THEN 7 WHEN '8' THEN 8 WHEN '9' THEN 9 WHEN 'T' THEN 8 WHEN 'L' THEN 9 WHEN 'K' THEN 9 WHEN 'D' THEN -1 WHEN 'U' THEN -1 WHEN 'X' THEN -1 WHEN 'N' THEN -1 ELSE -2 END END) = 0 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN 1 ELSE 0 END) AS HL_OCNT_CWPS0_182D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND (CASE WHEN TRIM(ACCOUNT_PAYMENT_STATUS) IS NULL THEN -3 ELSE CASE UPPER(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) WHEN '0' THEN 0 WHEN '1' THEN 1 WHEN '2' THEN 2 WHEN '3' THEN 3 WHEN '4' THEN 4 WHEN '5' THEN 5 WHEN '6' THEN 6 WHEN '7' THEN 7 WHEN '8' THEN 8 WHEN '9' THEN 9 WHEN 'T' THEN 8 WHEN 'L' THEN 9 WHEN 'K' THEN 9 WHEN 'D' THEN -1 WHEN 'U' THEN -1 WHEN 'X' THEN -1 WHEN 'N' THEN -1 ELSE -2 END END) = 0 AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN 1 ELSE 0 END) AS HL_OCNT_CWPS0_183D365D,
        -------Acik ve guncel odeme durumu 1-6 olan Kredi Adetleri -------------
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND (CASE WHEN TRIM(ACCOUNT_PAYMENT_STATUS) IS NULL THEN -3 ELSE CASE UPPER(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) WHEN '0' THEN 0 WHEN '1' THEN 1 WHEN '2' THEN 2 WHEN '3' THEN 3 WHEN '4' THEN 4 WHEN '5' THEN 5 WHEN '6' THEN 6 WHEN '7' THEN 7 WHEN '8' THEN 8 WHEN '9' THEN 9 WHEN 'T' THEN 8 WHEN 'L' THEN 9 WHEN 'K' THEN 9 WHEN 'D' THEN -1 WHEN 'U' THEN -1 WHEN 'X' THEN -1 WHEN 'N' THEN -1 ELSE -2 END END) BETWEEN 1 AND 6 THEN 1 ELSE 0 END) AS HL_OCNT_CWPS1_6_EVER,
