----------------------------------------
-- TMP4: Overdraft Line (OL_) Count Features
----------------------------------------

MKR_LONGLIST_TMP4 AS (

SELECT  A.ID,
        ------------------------------------------------------------------------
        ------- OVERDRAFT ------------------------------------------------------
        ------------------------------------------------------------------------
        -------Kullandirim Adetleri --------------------------------------------
        SUM(CASE WHEN CREDIT_TYPE_DRV = '002'                                               THEN 1 ELSE 0 END) AS OL_CNT_EVER,
        SUM(CASE WHEN CREDIT_TYPE_DRV = '002' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  30 THEN 1 ELSE 0 END) AS OL_CNT_30D,
        SUM(CASE WHEN CREDIT_TYPE_DRV = '002' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN 1 ELSE 0 END) AS OL_CNT_90D,
        SUM(CASE WHEN CREDIT_TYPE_DRV = '002' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN 1 ELSE 0 END) AS OL_CNT_182D,
        SUM(CASE WHEN CREDIT_TYPE_DRV = '002' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN 1 ELSE 0 END) AS OL_CNT_183D365D,
        -------Acik Kredi Adetleri----------------------------------------------
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002'                                               THEN 1 ELSE 0 END) AS OL_OCNT_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN 1 ELSE 0 END) AS OL_OCNT_90D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN 1 ELSE 0 END) AS OL_OCNT_182D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN 1 ELSE 0 END) AS OL_OCNT_183D365D,
        -------Acik ve Aktif Kredi Adetleri-------------------------------------
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND LAST_PAYMENT_DATE IS NOT NULL AND (TOTAL_OUTSTANDING_BALANCE > 0 OR (MKR_DATE - LAST_PAYMENT_DATE BETWEEN 0 AND 90))                                               THEN 1 ELSE 0 END) AS OL_OACCNT_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND LAST_PAYMENT_DATE IS NOT NULL AND (TOTAL_OUTSTANDING_BALANCE > 0 OR (MKR_DATE - LAST_PAYMENT_DATE BETWEEN 0 AND 90)) AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN 1 ELSE 0 END) AS OL_OACCNT_90D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND LAST_PAYMENT_DATE IS NOT NULL AND (TOTAL_OUTSTANDING_BALANCE > 0 OR (MKR_DATE - LAST_PAYMENT_DATE BETWEEN 0 AND 90)) AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN 1 ELSE 0 END) AS OL_OACCNT_182D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND LAST_PAYMENT_DATE IS NOT NULL AND (TOTAL_OUTSTANDING_BALANCE > 0 OR (MKR_DATE - LAST_PAYMENT_DATE BETWEEN 0 AND 90)) AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN 1 ELSE 0 END) AS OL_OACCNT_183D365D,
        ------ Acik, Limit Asim olan Kredi Adetleri
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND TOTAL_OUTSTANDING_BALANCE > LINE_AMOUNT_DRV THEN 1 ELSE 0 END) AS OL_OCNT_RSKOVERLMT,
        ------ Acik, Limit doluluk< 0.1 olan Kredi Adetleri
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND LINE_AMOUNT_DRV <> 0 AND TOTAL_OUTSTANDING_BALANCE / LINE_AMOUNT_DRV < 0.1 THEN 1 ELSE 0 END) AS OL_OCNT_LMTUSGLOW10P,
        ------ Acik ve Aktif,Limit doluluk< 0.1 olan Kredi Adetleri
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND LAST_PAYMENT_DATE IS NOT NULL AND LINE_AMOUNT_DRV <> 0 AND (TOTAL_OUTSTANDING_BALANCE > 0 OR (MKR_DATE - LAST_PAYMENT_DATE BETWEEN 0 AND 90)) AND TOTAL_OUTSTANDING_BALANCE / LINE_AMOUNT_DRV < 0.1 THEN 1 ELSE 0 END) AS OL_OACCNT_LMTUSGLOW10P,
        ------ Acik, Limit doluluk>= 0.5 olan Kredi Adetleri
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND LINE_AMOUNT_DRV <> 0 AND TOTAL_OUTSTANDING_BALANCE / LINE_AMOUNT_DRV >= 0.5                                             THEN 1 ELSE 0 END) AS OL_OCNT_LMTUSGHIGH50P,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND LINE_AMOUNT_DRV <> 0 AND TOTAL_OUTSTANDING_BALANCE / LINE_AMOUNT_DRV >= 0.5 AND MKR_DATE - GRANTED_ON BETWEEN 0 AND 182 THEN 1 ELSE 0 END) AS OL_OCNT_182D_LMTUSGHIGH50P,
        ------ Acik, Limit doluluk>= 0.8 olan Kredi Adetleri
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND LINE_AMOUNT_DRV <> 0 AND TOTAL_OUTSTANDING_BALANCE / LINE_AMOUNT_DRV >= 0.8                                             THEN 1 ELSE 0 END) AS OL_OCNT_LMTUSGHIGH80P,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND LINE_AMOUNT_DRV <> 0 AND TOTAL_OUTSTANDING_BALANCE / LINE_AMOUNT_DRV >= 0.8 AND MKR_DATE - GRANTED_ON BETWEEN 0 AND 182 THEN 1 ELSE 0 END) AS OL_OCNT_182D_LMTUSGHIGH80P,
        -------Acik ve guncel odeme durumu 0 olan Kredi Adetleri ---------------
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND (CASE WHEN TRIM(ACCOUNT_PAYMENT_STATUS) IS NULL THEN -3 ELSE CASE UPPER(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) WHEN '0' THEN 0 WHEN '1' THEN 1 WHEN '2' THEN 2 WHEN '3' THEN 3 WHEN '4' THEN 4 WHEN '5' THEN 5 WHEN '6' THEN 6 WHEN '7' THEN 7 WHEN '8' THEN 8 WHEN '9' THEN 9 WHEN 'T' THEN 8 WHEN 'L' THEN 9 WHEN 'K' THEN 9 WHEN 'D' THEN -1 WHEN 'U' THEN -1 WHEN 'X' THEN -1 WHEN 'N' THEN -1 ELSE -2 END END) = 0                                               THEN 1 ELSE 0 END) AS OL_OCNT_CWPS0_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND (CASE WHEN TRIM(ACCOUNT_PAYMENT_STATUS) IS NULL THEN -3 ELSE CASE UPPER(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) WHEN '0' THEN 0 WHEN '1' THEN 1 WHEN '2' THEN 2 WHEN '3' THEN 3 WHEN '4' THEN 4 WHEN '5' THEN 5 WHEN '6' THEN 6 WHEN '7' THEN 7 WHEN '8' THEN 8 WHEN '9' THEN 9 WHEN 'T' THEN 8 WHEN 'L' THEN 9 WHEN 'K' THEN 9 WHEN 'D' THEN -1 WHEN 'U' THEN -1 WHEN 'X' THEN -1 WHEN 'N' THEN -1 ELSE -2 END END) = 0 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN 1 ELSE 0 END) AS OL_OCNT_CWPS0_90D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND (CASE WHEN TRIM(ACCOUNT_PAYMENT_STATUS) IS NULL THEN -3 ELSE CASE UPPER(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) WHEN '0' THEN 0 WHEN '1' THEN 1 WHEN '2' THEN 2 WHEN '3' THEN 3 WHEN '4' THEN 4 WHEN '5' THEN 5 WHEN '6' THEN 6 WHEN '7' THEN 7 WHEN '8' THEN 8 WHEN '9' THEN 9 WHEN 'T' THEN 8 WHEN 'L' THEN 9 WHEN 'K' THEN 9 WHEN 'D' THEN -1 WHEN 'U' THEN -1 WHEN 'X' THEN -1 WHEN 'N' THEN -1 ELSE -2 END END) = 0 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN 1 ELSE 0 END) AS OL_OCNT_CWPS0_182D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND (CASE WHEN TRIM(ACCOUNT_PAYMENT_STATUS) IS NULL THEN -3 ELSE CASE UPPER(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) WHEN '0' THEN 0 WHEN '1' THEN 1 WHEN '2' THEN 2 WHEN '3' THEN 3 WHEN '4' THEN 4 WHEN '5' THEN 5 WHEN '6' THEN 6 WHEN '7' THEN 7 WHEN '8' THEN 8 WHEN '9' THEN 9 WHEN 'T' THEN 8 WHEN 'L' THEN 9 WHEN 'K' THEN 9 WHEN 'D' THEN -1 WHEN 'U' THEN -1 WHEN 'X' THEN -1 WHEN 'N' THEN -1 ELSE -2 END END) = 0 AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN 1 ELSE 0 END) AS OL_OCNT_CWPS0_183D365D,
        -------Acik ve Aktif ve guncel odeme durumu 0 olan Kredi Adetleri ------
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND LAST_PAYMENT_DATE IS NOT NULL AND (TOTAL_OUTSTANDING_BALANCE > 0 OR (MKR_DATE - LAST_PAYMENT_DATE BETWEEN 0 AND 90)) AND (CASE WHEN TRIM(ACCOUNT_PAYMENT_STATUS) IS NULL THEN -3 ELSE CASE UPPER(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) WHEN '0' THEN 0 WHEN '1' THEN 1 WHEN '2' THEN 2 WHEN '3' THEN 3 WHEN '4' THEN 4 WHEN '5' THEN 5 WHEN '6' THEN 6 WHEN '7' THEN 7 WHEN '8' THEN 8 WHEN '9' THEN 9 WHEN 'T' THEN 8 WHEN 'L' THEN 9 WHEN 'K' THEN 9 WHEN 'D' THEN -1 WHEN 'U' THEN -1 WHEN 'X' THEN -1 WHEN 'N' THEN -1 ELSE -2 END END) = 0 THEN 1 ELSE 0 END) AS OL_OACCNT_CWPS0_EVER,
        -------Acik ve guncel odeme durumu 1-6 olan Kredi Adetleri -------------
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND (CASE WHEN TRIM(ACCOUNT_PAYMENT_STATUS) IS NULL THEN -3 ELSE CASE UPPER(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) WHEN '0' THEN 0 WHEN '1' THEN 1 WHEN '2' THEN 2 WHEN '3' THEN 3 WHEN '4' THEN 4 WHEN '5' THEN 5 WHEN '6' THEN 6 WHEN '7' THEN 7 WHEN '8' THEN 8 WHEN '9' THEN 9 WHEN 'T' THEN 8 WHEN 'L' THEN 9 WHEN 'K' THEN 9 WHEN 'D' THEN -1 WHEN 'U' THEN -1 WHEN 'X' THEN -1 WHEN 'N' THEN -1 ELSE -2 END END) BETWEEN 1 AND 6                                               THEN 1 ELSE 0 END) AS OL_OCNT_CWPS1_6_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND (CASE WHEN TRIM(ACCOUNT_PAYMENT_STATUS) IS NULL THEN -3 ELSE CASE UPPER(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) WHEN '0' THEN 0 WHEN '1' THEN 1 WHEN '2' THEN 2 WHEN '3' THEN 3 WHEN '4' THEN 4 WHEN '5' THEN 5 WHEN '6' THEN 6 WHEN '7' THEN 7 WHEN '8' THEN 8 WHEN '9' THEN 9 WHEN 'T' THEN 8 WHEN 'L' THEN 9 WHEN 'K' THEN 9 WHEN 'D' THEN -1 WHEN 'U' THEN -1 WHEN 'X' THEN -1 WHEN 'N' THEN -1 ELSE -2 END END) BETWEEN 1 AND 6 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN 1 ELSE 0 END) AS OL_OCNT_CWPS1_6_90D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND (CASE WHEN TRIM(ACCOUNT_PAYMENT_STATUS) IS NULL THEN -3 ELSE CASE UPPER(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) WHEN '0' THEN 0 WHEN '1' THEN 1 WHEN '2' THEN 2 WHEN '3' THEN 3 WHEN '4' THEN 4 WHEN '5' THEN 5 WHEN '6' THEN 6 WHEN '7' THEN 7 WHEN '8' THEN 8 WHEN '9' THEN 9 WHEN 'T' THEN 8 WHEN 'L' THEN 9 WHEN 'K' THEN 9 WHEN 'D' THEN -1 WHEN 'U' THEN -1 WHEN 'X' THEN -1 WHEN 'N' THEN -1 ELSE -2 END END) BETWEEN 1 AND 6 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN 1 ELSE 0 END) AS OL_OCNT_CWPS1_6_182D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND (CASE WHEN TRIM(ACCOUNT_PAYMENT_STATUS) IS NULL THEN -3 ELSE CASE UPPER(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) WHEN '0' THEN 0 WHEN '1' THEN 1 WHEN '2' THEN 2 WHEN '3' THEN 3 WHEN '4' THEN 4 WHEN '5' THEN 5 WHEN '6' THEN 6 WHEN '7' THEN 7 WHEN '8' THEN 8 WHEN '9' THEN 9 WHEN 'T' THEN 8 WHEN 'L' THEN 9 WHEN 'K' THEN 9 WHEN 'D' THEN -1 WHEN 'U' THEN -1 WHEN 'X' THEN -1 WHEN 'N' THEN -1 ELSE -2 END END) BETWEEN 1 AND 6 AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN 1 ELSE 0 END) AS OL_OCNT_CWPS1_6_183D365D,
        -------Acik ve guncel odeme durumu > 6 olan Kredi Adetleri -------------
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND (CASE WHEN TRIM(ACCOUNT_PAYMENT_STATUS) IS NULL THEN -3 ELSE CASE UPPER(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) WHEN '0' THEN 0 WHEN '1' THEN 1 WHEN '2' THEN 2 WHEN '3' THEN 3 WHEN '4' THEN 4 WHEN '5' THEN 5 WHEN '6' THEN 6 WHEN '7' THEN 7 WHEN '8' THEN 8 WHEN '9' THEN 9 WHEN 'T' THEN 8 WHEN 'L' THEN 9 WHEN 'K' THEN 9 WHEN 'D' THEN -1 WHEN 'U' THEN -1 WHEN 'X' THEN -1 WHEN 'N' THEN -1 ELSE -2 END END) > 6                                               THEN 1 ELSE 0 END) AS OL_OCNT_CWPS6P_EVER,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND (CASE WHEN TRIM(ACCOUNT_PAYMENT_STATUS) IS NULL THEN -3 ELSE CASE UPPER(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) WHEN '0' THEN 0 WHEN '1' THEN 1 WHEN '2' THEN 2 WHEN '3' THEN 3 WHEN '4' THEN 4 WHEN '5' THEN 5 WHEN '6' THEN 6 WHEN '7' THEN 7 WHEN '8' THEN 8 WHEN '9' THEN 9 WHEN 'T' THEN 8 WHEN 'L' THEN 9 WHEN 'K' THEN 9 WHEN 'D' THEN -1 WHEN 'U' THEN -1 WHEN 'X' THEN -1 WHEN 'N' THEN -1 ELSE -2 END END) > 6 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN 1 ELSE 0 END) AS OL_OCNT_CWPS6P_90D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND (CASE WHEN TRIM(ACCOUNT_PAYMENT_STATUS) IS NULL THEN -3 ELSE CASE UPPER(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) WHEN '0' THEN 0 WHEN '1' THEN 1 WHEN '2' THEN 2 WHEN '3' THEN 3 WHEN '4' THEN 4 WHEN '5' THEN 5 WHEN '6' THEN 6 WHEN '7' THEN 7 WHEN '8' THEN 8 WHEN '9' THEN 9 WHEN 'T' THEN 8 WHEN 'L' THEN 9 WHEN 'K' THEN 9 WHEN 'D' THEN -1 WHEN 'U' THEN -1 WHEN 'X' THEN -1 WHEN 'N' THEN -1 ELSE -2 END END) > 6 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN 1 ELSE 0 END) AS OL_OCNT_CWPS6P_182D,
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND (CASE WHEN TRIM(ACCOUNT_PAYMENT_STATUS) IS NULL THEN -3 ELSE CASE UPPER(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) WHEN '0' THEN 0 WHEN '1' THEN 1 WHEN '2' THEN 2 WHEN '3' THEN 3 WHEN '4' THEN 4 WHEN '5' THEN 5 WHEN '6' THEN 6 WHEN '7' THEN 7 WHEN '8' THEN 8 WHEN '9' THEN 9 WHEN 'T' THEN 8 WHEN 'L' THEN 9 WHEN 'K' THEN 9 WHEN 'D' THEN -1 WHEN 'U' THEN -1 WHEN 'X' THEN -1 WHEN 'N' THEN -1 ELSE -2 END END) > 6 AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN 1 ELSE 0 END) AS OL_OCNT_CWPS6P_183D365D,
        -------Acik ve guncel odeme durumu belirsiz olan Kredi Adetleri --------
        SUM(CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '002' AND (CASE WHEN TRIM(ACCOUNT_PAYMENT_STATUS) IS NULL THEN -3 ELSE CASE UPPER(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 1)) WHEN '0' THEN 0 WHEN '1' THEN 1 WHEN '2' THEN 2 WHEN '3' THEN 3 WHEN '4' THEN 4 WHEN '5' THEN 5 WHEN '6' THEN 6 WHEN '7' THEN 7 WHEN '8' THEN 8 WHEN '9' THEN 9 WHEN 'T' THEN 8 WHEN 'L' THEN 9 WHEN 'K' THEN 9 WHEN 'D' THEN -1 WHEN 'U' THEN -1 WHEN 'X' THEN -1 WHEN 'N' THEN -1 ELSE -2 END END) < 0 THEN 1 ELSE 0 END) AS OL_OCNT_CWPSUD_EVER,
        -------Acik, son 6 ay en kotu odeme statusu, Kredi Adetleri ------------
