        SUM(CASE WHEN CREDIT_STATUS_DRV = '008' AND CREDIT_TYPE_DRV = '300' AND INSTR(SUBSTR(ACCOUNT_PAYMENT_STATUS, 1, 12),2) > 0 AND MKR_DATE - MN_OVERDUE_DAYS_90_DT BETWEEN   0 AND 182 THEN INSTALLMENT_AMOUNT END) AS HL_BDCLSSMINS_DLQ2_182D,
