        ------ Acik, Bank of Baku haric maksimum tutar----------------------------
        MAX(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300'                                               THEN INITIAL_AMOUNT_DRV END) AS HL_OMXAMT_EVER_O,
        MAX(CASE WHEN OWN_DATA_FLAG = 0 AND CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '300' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN INITIAL_AMOUNT_DRV END) AS HL_OMXAMT_90D_O,
