MKR_LONGLIST_TMP15 AS (

SELECT  A.ID,
		------------------------ Tekil banka sayisi ----------------------------
        ------------------------------------------------------------------------
        ------- TUKETICI KREDILERI ---------------------------------------------
        ------------------------------------------------------------------------
        ---- Kullandirim -----------------
        COUNT(DISTINCT (CASE WHEN CREDIT_TYPE_DRV = '001' THEN BANK_ID END)) AS CL_ALLBNK_EVER,
        ---- Acik ------------------------
        COUNT(DISTINCT (CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001'                                               THEN BANK_ID END)) AS CL_BNK_EVER,
        COUNT(DISTINCT (CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN BANK_ID END)) AS CL_BNK_90D,
        COUNT(DISTINCT (CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN  91 AND 365 THEN BANK_ID END)) AS CL_BNK_91D365D,
        COUNT(DISTINCT (CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN BANK_ID END)) AS CL_BNK_182D,
        COUNT(DISTINCT (CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV = '001' AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN BANK_ID END)) AS CL_BNK_183D365D,
