        COUNT(DISTINCT (CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV IN ('002', '003') AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN BANK_ID END)) AS CCOL_BNK_183D365D,
