        COUNT(DISTINCT (CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV IN ('002', '003') AND LINE_AMOUNT_DRV > 0 AND TOTAL_OUTSTANDING_BALANCE / LINE_AMOUNT_DRV >= 0.8 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND  90 THEN BANK_ID END)) AS CCOL_BNK_LMTUSGHIGH80P_90D,
        COUNT(DISTINCT (CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV IN ('002', '003') AND LINE_AMOUNT_DRV > 0 AND TOTAL_OUTSTANDING_BALANCE / LINE_AMOUNT_DRV >= 0.8 AND MKR_DATE - GRANTED_ON BETWEEN  91 AND 365 THEN BANK_ID END)) AS CCOL_BNK_LMTUSGHIGH80P_91D365D,
        COUNT(DISTINCT (CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV IN ('002', '003') AND LINE_AMOUNT_DRV > 0 AND TOTAL_OUTSTANDING_BALANCE / LINE_AMOUNT_DRV >= 0.8 AND MKR_DATE - GRANTED_ON BETWEEN   0 AND 182 THEN BANK_ID END)) AS CCOL_BNK_LMTUSGHIGH80P_182D,
        COUNT(DISTINCT (CASE WHEN CREDIT_STATUS_DRV = '007' AND CREDIT_TYPE_DRV IN ('002', '003') AND LINE_AMOUNT_DRV > 0 AND TOTAL_OUTSTANDING_BALANCE / LINE_AMOUNT_DRV >= 0.8 AND MKR_DATE - GRANTED_ON BETWEEN 183 AND 365 THEN BANK_ID END)) AS CCOL_BNK_LMTUSGHGH80P_183D365D,
