             WHEN CL_OSMAMT_CWPS0_182D IS NOT NULL AND CL_OSMAMT_CWPS0_183D365D IS NULL THEN CL_OSMAMT_CWPS0_182D
             ELSE CL_OSMAMT_CWPS0_183D365D
        END AS CL_OSMAMT_CWPS0_365D,
        CASE WHEN CL_OCNT_CWPS0_EVER > 0 THEN CL_OSMAMT_CWPS0_EVER / CL_OCNT_CWPS0_EVER END AS CL_OAVGAMT_CWPS0_EVER,
        CASE WHEN CL_OCNT_CWPS0_90D > 0 THEN CL_OSMAMT_CWPS0_90D / CL_OCNT_CWPS0_90D END AS CL_OAVGAMT_CWPS0_90D,
        CASE WHEN CL_OCNT_CWPS0_182D > 0 THEN CL_OSMAMT_CWPS0_182D / CL_OCNT_CWPS0_182D END AS CL_OAVGAMT_CWPS0_182D,
        CASE WHEN CL_OCNT_CWPS0_183D365D > 0 THEN CL_OSMAMT_CWPS0_183D365D / CL_OCNT_CWPS0_183D365D END AS CL_OAVGAMT_CWPS0_183D365D,
        CASE WHEN (NVL(CL_OCNT_CWPS0_182D, 0) + NVL(CL_OCNT_CWPS0_183D365D, 0)) > 0 THEN (NVL(CL_OSMAMT_CWPS0_182D, 0) + NVL(CL_OSMAMT_CWPS0_183D365D, 0)) / (NVL(CL_OCNT_CWPS0_182D, 0) + NVL(CL_OCNT_CWPS0_183D365D, 0)) END AS CL_OAVGAMT_CWPS0_365D,
        CL_OSMTOB_CWPS0_EVER,
        CL_OSMTOB_CWPS0_90D,
        CL_OSMTOB_CWPS0_182D,
        CL_OSMTOB_CWPS0_183D365D,
        CASE WHEN CL_OSMTOB_CWPS0_182D IS NOT NULL AND CL_OSMTOB_CWPS0_183D365D IS NOT NULL THEN CL_OSMTOB_CWPS0_182D + CL_OSMTOB_CWPS0_183D365D
             WHEN CL_OSMTOB_CWPS0_182D IS NOT NULL AND CL_OSMTOB_CWPS0_183D365D IS NULL THEN CL_OSMTOB_CWPS0_182D
             ELSE CL_OSMTOB_CWPS0_183D365D
