        CASE WHEN CL_OCNT_CWPS0_90D > 0 THEN CL_OSMTOB_CWPS0_90D / CL_OCNT_CWPS0_90D END AS CL_OAVGTOB_CWPS0_90D,
        CASE WHEN CL_OCNT_CWPS0_182D > 0 THEN CL_OSMTOB_CWPS0_182D / CL_OCNT_CWPS0_182D END AS CL_OAVGTOB_CWPS0_182D,
        CASE WHEN CL_OCNT_CWPS0_183D365D > 0 THEN CL_OSMTOB_CWPS0_183D365D / CL_OCNT_CWPS0_183D365D END AS CL_OAVGTOB_CWPS0_183D365D,
        CASE WHEN (NVL(CL_OCNT_CWPS0_182D, 0) + NVL(CL_OCNT_CWPS0_183D365D, 0)) > 0 THEN (NVL(CL_OSMTOB_CWPS0_182D, 0) + NVL(CL_OSMTOB_CWPS0_183D365D, 0)) / (NVL(CL_OCNT_CWPS0_182D, 0) + NVL(CL_OCNT_CWPS0_183D365D, 0)) END AS CL_OAVGTOB_CWPS0_365D,
