             WHEN CL_OMXAMT_182D IS NOT NULL AND CL_OMXAMT_183D365D_O IS NULL THEN CL_OMXAMT_182D
             ELSE CL_OMXAMT_183D365D_O
        END AS CL_OMXAMT_365D_O,
