        CL_OSMAMT_90D_O,
        CL_OSMAMT_182D_O,
        CL_OSMAMT_183D365D_O,
        CASE WHEN CL_OSMAMT_182D IS NOT NULL AND CL_OSMAMT_183D365D_O IS NOT NULL THEN CL_OSMAMT_182D + CL_OSMAMT_183D365D_O
             WHEN CL_OSMAMT_182D IS NOT NULL AND CL_OSMAMT_183D365D_O IS NULL THEN CL_OSMAMT_182D
             ELSE CL_OSMAMT_183D365D_O
        END AS CL_OSMAMT_365D_O,
