        CASE WHEN CL_OCNT_90D_O > 0 THEN CL_OSMAMT_90D_O / CL_OCNT_90D_O END AS CL_OAVGAMT_90D_O,
        CASE WHEN CL_OCNT_182D_O > 0 THEN CL_OSMAMT_182D_O / CL_OCNT_182D_O END AS CL_OAVGAMT_182D_O,
        CASE WHEN CL_OCNT_183D365D_O > 0 THEN CL_OSMAMT_183D365D_O / CL_OCNT_183D365D_O END AS CL_OAVGAMT_183D365D_O,
        CASE WHEN (NVL(CL_OCNT_182D_O, 0) + NVL(CL_OCNT_183D365D_O, 0)) > 0 THEN (NVL(CL_OSMAMT_182D_O, 0) + NVL(CL_OSMAMT_183D365D_O, 0)) / (NVL(CL_OCNT_182D_O, 0) + NVL(CL_OCNT_183D365D_O, 0)) END AS CL_OAVGAMT_365D_O,
        CL_OMXTOB_EVER_O,
        CL_OMXTOB_90D_O,
        CL_OMXTOB_182D_O,
        CL_OMXTOB_183D365D_O,
        CASE WHEN CL_OMXTOB_182D IS NOT NULL AND CL_OMXTOB_183D365D_O IS NOT NULL THEN CL_OMXTOB_182D + CL_OMXTOB_183D365D_O
             WHEN CL_OMXTOB_182D IS NOT NULL AND CL_OMXTOB_183D365D_O IS NULL THEN CL_OMXTOB_182D
             ELSE CL_OMXTOB_183D365D_O
        END AS CL_OMXTOB_365D_O,
        CL_OSMTOB_EVER_O,
        CL_OSMTOB_90D_O,
        CL_OSMTOB_182D_O,
        CL_OSMTOB_183D365D_O,
        CASE WHEN CL_OSMTOB_182D IS NOT NULL AND CL_OSMTOB_183D365D_O IS NOT NULL THEN CL_OSMTOB_182D + CL_OSMTOB_183D365D_O
             WHEN CL_OSMTOB_182D IS NOT NULL AND CL_OSMTOB_183D365D_O IS NULL THEN CL_OSMTOB_182D
             ELSE CL_OSMTOB_183D365D_O
        END AS CL_OSMTOB_365D_O,
        CASE WHEN CL_OCNT_EVER_O > 0 THEN CL_OSMTOB_EVER_O / CL_OCNT_EVER_O END AS CL_OAVGTOB_EVER_O,
        CASE WHEN CL_OCNT_90D_O > 0 THEN CL_OSMTOB_90D_O / CL_OCNT_90D_O END AS CL_OAVGTOB_90D_O,
        CASE WHEN CL_OCNT_182D_O > 0 THEN CL_OSMTOB_182D_O / CL_OCNT_182D_O END AS CL_OAVGTOB_182D_O,
        CASE WHEN CL_OCNT_183D365D_O > 0 THEN CL_OSMTOB_183D365D_O / CL_OCNT_183D365D_O END AS CL_OAVGTOB_183D365D_O,
        CASE WHEN (NVL(CL_OCNT_182D_O, 0) + NVL(CL_OCNT_183D365D_O, 0)) > 0 THEN (NVL(CL_OSMTOB_182D_O, 0) + NVL(CL_OSMTOB_183D365D_O, 0)) / (NVL(CL_OCNT_182D_O, 0) + NVL(CL_OCNT_183D365D_O, 0)) END AS CL_OAVGTOB_365D_O,
