----------------------------------------
-- MKR_LONGLIST_OTHRAMT: Other Amount Features (Closed, Historical)
----------------------------------------

MKR_LONGLIST_OTHRAMT AS (

SELECT  K.ID,
        CL_MXAMT_EVER,
        CL_MXAMT_30D,
        CL_MXAMT_90D,
        CL_MXAMT_91D365D,
        CL_MXAMT_182D,
        CL_MXAMT_183D365D,
        CASE WHEN CL_MXAMT_182D IS NOT NULL AND CL_MXAMT_183D365D IS NOT NULL THEN GREATEST(CL_MXAMT_182D,CL_MXAMT_183D365D)
             WHEN CL_MXAMT_182D IS NOT NULL AND CL_MXAMT_183D365D IS NULL THEN CL_MXAMT_182D
             ELSE CL_MXAMT_183D365D
        END AS CL_MXAMT_365D,
        CL_MXINS_EVER,
        CL_MXINS_30D,
        CL_MXINS_90D,
        CL_MXINS_91D365D,
        CL_MXINS_182D,
        CL_MXINS_183D365D,
        CASE WHEN CL_MXINS_182D IS NOT NULL AND CL_MXINS_183D365D IS NOT NULL THEN GREATEST(CL_MXINS_182D,CL_MXINS_183D365D)
             WHEN CL_MXINS_182D IS NOT NULL AND CL_MXINS_183D365D IS NULL THEN CL_MXINS_182D
             ELSE CL_MXINS_183D365D
        END AS CL_MXINS_365D,
        CL_AVGAMT_EVER,
        CL_AVGAMT_30D,
        CL_AVGAMT_90D,
        CL_AVGAMT_91D365D,
        CL_AVGAMT_182D,
        CL_AVGAMT_183D365D,
        CASE WHEN CL_AVGAMT_182D IS NOT NULL AND CL_AVGAMT_183D365D IS NOT NULL THEN (CL_CNT_182D*CL_AVGAMT_182D + CL_CNT_183D365D*CL_AVGAMT_183D365D) / (CL_CNT_182D + CL_CNT_183D365D)
             WHEN CL_AVGAMT_182D IS NOT NULL AND CL_AVGAMT_183D365D IS NULL THEN CL_AVGAMT_182D
             ELSE CL_AVGAMT_183D365D
        END AS CL_AVGAMT_365D,
        CL_AVGINS_EVER,
        CL_AVGINS_30D,
        CL_AVGINS_90D,
        CL_AVGINS_91D365D,
        CL_AVGINS_182D,
        CL_AVGINS_183D365D,
        CASE WHEN CL_AVGINS_182D IS NOT NULL AND CL_AVGINS_183D365D IS NOT NULL THEN (CL_CNT_182D*CL_AVGINS_182D + CL_CNT_183D365D*CL_AVGINS_183D365D) / (CL_CNT_182D + CL_CNT_183D365D)
             WHEN CL_AVGINS_182D IS NOT NULL AND CL_AVGINS_183D365D IS NULL THEN CL_AVGINS_182D
             ELSE CL_AVGINS_183D365D
        END AS CL_AVGINS_365D,
        CL_GDCLSMXAMT_EVER,
        CL_GDCLSMXAMT_90D,
        CL_GDCLSMXAMT_182D,
        CL_GDCLSMXAMT_183D365D,
        CASE WHEN CL_GDCLSMXAMT_182D IS NOT NULL AND CL_GDCLSMXAMT_183D365D IS NOT NULL THEN GREATEST(CL_GDCLSMXAMT_182D,CL_GDCLSMXAMT_183D365D)
             WHEN CL_GDCLSMXAMT_182D IS NOT NULL AND CL_GDCLSMXAMT_183D365D IS NULL THEN CL_GDCLSMXAMT_182D
             ELSE CL_GDCLSMXAMT_183D365D
        END AS CL_GDCLSMXAMT_365D,
        CL_GDCLSMXINS_EVER,
        CL_GDCLSMXINS_90D,
        CL_GDCLSMXINS_182D,
        CL_GDCLSMXINS_183D365D,
        CASE WHEN CL_GDCLSMXINS_182D IS NOT NULL AND CL_GDCLSMXINS_183D365D IS NOT NULL THEN GREATEST(CL_GDCLSMXINS_182D,CL_GDCLSMXINS_183D365D)
             WHEN CL_GDCLSMXINS_182D IS NOT NULL AND CL_GDCLSMXINS_183D365D IS NULL THEN CL_GDCLSMXINS_182D
             ELSE CL_GDCLSMXINS_183D365D
        END AS CL_GDCLSMXINS_365D,
        CL_GDCLSSMAMT_EVER,
        CL_GDCLSSMAMT_90D,
        CL_GDCLSSMAMT_182D,
        CL_GDCLSSMAMT_183D365D,
        CASE WHEN CL_GDCLSSMAMT_182D IS NOT NULL AND CL_GDCLSSMAMT_183D365D IS NOT NULL THEN CL_GDCLSSMAMT_182D + CL_GDCLSSMAMT_183D365D
             WHEN CL_GDCLSSMAMT_182D IS NOT NULL AND CL_GDCLSSMAMT_183D365D IS NULL THEN CL_GDCLSSMAMT_182D
             ELSE CL_GDCLSSMAMT_183D365D
        END AS CL_GDCLSSMAMT_365D,
        CASE WHEN CL_GDCLSCNT_EVER > 0 THEN CL_GDCLSSMAMT_EVER / CL_GDCLSCNT_EVER END AS CL_GDCLSAVGAMT_EVER,
        CASE WHEN CL_GDCLSCNT_90D > 0 THEN CL_GDCLSSMAMT_90D / CL_GDCLSCNT_90D END AS CL_GDCLSAVGAMT_90D,
        CASE WHEN CL_GDCLSCNT_182D > 0 THEN CL_GDCLSSMAMT_182D / CL_GDCLSCNT_182D END AS CL_GDCLSAVGAMT_182D,
        CASE WHEN CL_GDCLSCNT_183D365D > 0 THEN CL_GDCLSSMAMT_183D365D / CL_GDCLSCNT_183D365D END AS CL_GDCLSAVGAMT_183D365D,
        CASE WHEN (NVL(CL_GDCLSCNT_182D, 0) + NVL(CL_GDCLSCNT_183D365D, 0)) > 0 THEN (NVL(CL_GDCLSSMAMT_182D, 0) + NVL(CL_GDCLSSMAMT_183D365D, 0)) / (NVL(CL_GDCLSCNT_182D, 0) + NVL(CL_GDCLSCNT_183D365D, 0)) END AS CL_GDCLSAVGAMT_365D,
        CL_GDCLSSMINS_EVER,
        CL_GDCLSSMINS_90D,
