        CL_GDCLSMXINS_MXDLQ0_90D,
        CL_GDCLSMXINS_MXDLQ0_182D,
        CL_GDCLSMXINS_MXDLQ0_183D365D,
        CASE WHEN CL_GDCLSMXINS_MXDLQ0_182D IS NOT NULL AND CL_GDCLSMXINS_MXDLQ0_183D365D IS NOT NULL THEN GREATEST(CL_GDCLSMXINS_MXDLQ0_182D,CL_GDCLSMXINS_MXDLQ0_183D365D)
             WHEN CL_GDCLSMXINS_MXDLQ0_182D IS NOT NULL AND CL_GDCLSMXINS_MXDLQ0_183D365D IS NULL THEN CL_GDCLSMXINS_MXDLQ0_182D
             ELSE CL_GDCLSMXINS_MXDLQ0_183D365D
        END AS CL_GDCLSMXINS_MXDLQ0_365D,
        CL_GDCLSSMAMT_MXDLQ0_EVER,
        CL_GDCLSSMAMT_MXDLQ0_90D,
        CL_GDCLSSMAMT_MXDLQ0_182D,
        CL_GDCLSSMAMT_MXDLQ0_183D365D,
        CASE WHEN CL_GDCLSSMAMT_MXDLQ0_182D IS NOT NULL AND CL_GDCLSSMAMT_MXDLQ0_183D365D IS NOT NULL THEN CL_GDCLSSMAMT_MXDLQ0_182D + CL_GDCLSSMAMT_MXDLQ0_183D365D
             WHEN CL_GDCLSSMAMT_MXDLQ0_182D IS NOT NULL AND CL_GDCLSSMAMT_MXDLQ0_183D365D IS NULL THEN CL_GDCLSSMAMT_MXDLQ0_182D
             ELSE CL_GDCLSSMAMT_MXDLQ0_183D365D
        END AS CL_GDCLSSMAMT_MXDLQ0_365D,
