        CASE WHEN (NVL(OL_GDCLSCNT_MXDLQ1_182D, 0) + NVL(OL_GDCLSCNT_MXDLQ1_183D365D, 0)) > 0 THEN (NVL(OL_GDCLSSMLMT_MXDLQ1_182D, 0) + NVL(OL_GDCLSSMLMT_MXDLQ1_183D365D, 0)) / (NVL(OL_GDCLSCNT_MXDLQ1_182D, 0) + NVL(OL_GDCLSCNT_MXDLQ1_183D365D, 0)) END AS OL_GDCLSAVGLMT_MXDLQ1_365D,
        OL_BDCLSMXLMT_EVER,
        OL_BDCLSMXLMT_90D,
        OL_BDCLSMXLMT_182D,
        OL_BDCLSMXLMT_183D365D,
        CASE WHEN OL_BDCLSMXLMT_182D IS NOT NULL AND OL_BDCLSMXLMT_183D365D IS NOT NULL THEN GREATEST(OL_BDCLSMXLMT_182D,OL_BDCLSMXLMT_183D365D)
             WHEN OL_BDCLSMXLMT_182D IS NOT NULL AND OL_BDCLSMXLMT_183D365D IS NULL THEN OL_BDCLSMXLMT_182D
             ELSE OL_BDCLSMXLMT_183D365D
        END AS OL_BDCLSMXLMT_365D,
        OL_BDCLSSMLMT_EVER,
        OL_BDCLSSMLMT_90D,
        OL_BDCLSSMLMT_182D,
        OL_BDCLSSMLMT_183D365D,
        CASE WHEN OL_BDCLSSMLMT_182D IS NOT NULL AND OL_BDCLSSMLMT_183D365D IS NOT NULL THEN OL_BDCLSSMLMT_182D + OL_BDCLSSMLMT_183D365D
             WHEN OL_BDCLSSMLMT_182D IS NOT NULL AND OL_BDCLSSMLMT_183D365D IS NULL THEN OL_BDCLSSMLMT_182D
             ELSE OL_BDCLSSMLMT_183D365D
        END AS OL_BDCLSSMLMT_365D,
        CASE WHEN OL_BDCLSCNT_EVER > 0 THEN OL_BDCLSSMLMT_EVER / OL_BDCLSCNT_EVER END AS OL_BDCLSAVGLMT_EVER,
        CASE WHEN OL_BDCLSCNT_90D > 0 THEN OL_BDCLSSMLMT_90D / OL_BDCLSCNT_90D END AS OL_BDCLSAVGLMT_90D,
        CASE WHEN OL_BDCLSCNT_182D > 0 THEN OL_BDCLSSMLMT_182D / OL_BDCLSCNT_182D END AS OL_BDCLSAVGLMT_182D,
        CASE WHEN OL_BDCLSCNT_183D365D > 0 THEN OL_BDCLSSMLMT_183D365D / OL_BDCLSCNT_183D365D END AS OL_BDCLSAVGLMT_183D365D,
        CASE WHEN (NVL(OL_BDCLSCNT_182D, 0) + NVL(OL_BDCLSCNT_183D365D, 0)) > 0 THEN (NVL(OL_BDCLSSMLMT_182D, 0) + NVL(OL_BDCLSSMLMT_183D365D, 0)) / (NVL(OL_BDCLSCNT_182D, 0) + NVL(OL_BDCLSCNT_183D365D, 0)) END AS OL_BDCLSAVGLMT_365D,
        OL_BDCLSMXLMT_DLQ2_EVER,
        OL_BDCLSMXLMT_DLQ2_90D,
        OL_BDCLSMXLMT_DLQ2_182D,
        OL_BDCLSMXLMT_DLQ2_183D365D,
        CASE WHEN OL_BDCLSMXLMT_DLQ2_182D IS NOT NULL AND OL_BDCLSMXLMT_DLQ2_183D365D IS NOT NULL THEN GREATEST(OL_BDCLSMXLMT_DLQ2_182D,OL_BDCLSMXLMT_DLQ2_183D365D)
             WHEN OL_BDCLSMXLMT_DLQ2_182D IS NOT NULL AND OL_BDCLSMXLMT_DLQ2_183D365D IS NULL THEN OL_BDCLSMXLMT_DLQ2_182D
             ELSE OL_BDCLSMXLMT_DLQ2_183D365D
        END AS OL_BDCLSMXLMT_DLQ2_365D,
        OL_BDCLSSMLMT_DLQ2_EVER,
        OL_BDCLSSMLMT_DLQ2_90D,
        OL_BDCLSSMLMT_DLQ2_182D,
        OL_BDCLSSMLMT_DLQ2_183D365D,
        CASE WHEN OL_BDCLSSMLMT_DLQ2_182D IS NOT NULL AND OL_BDCLSSMLMT_DLQ2_183D365D IS NOT NULL THEN OL_BDCLSSMLMT_DLQ2_182D + OL_BDCLSSMLMT_DLQ2_183D365D
             WHEN OL_BDCLSSMLMT_DLQ2_182D IS NOT NULL AND OL_BDCLSSMLMT_DLQ2_183D365D IS NULL THEN OL_BDCLSSMLMT_DLQ2_182D
             ELSE OL_BDCLSSMLMT_DLQ2_183D365D
        END AS OL_BDCLSSMLMT_DLQ2_365D,
        CASE WHEN OL_BDCLSCNT_DLQ2_EVER > 0 THEN OL_BDCLSSMLMT_DLQ2_EVER / OL_BDCLSCNT_DLQ2_EVER END AS OL_BDCLSAVGLMT_DLQ2_EVER,
        CASE WHEN OL_BDCLSCNT_DLQ2_90D > 0 THEN OL_BDCLSSMLMT_DLQ2_90D / OL_BDCLSCNT_DLQ2_90D END AS OL_BDCLSAVGLMT_DLQ2_90D,
        CASE WHEN OL_BDCLSCNT_DLQ2_182D > 0 THEN OL_BDCLSSMLMT_DLQ2_182D / OL_BDCLSCNT_DLQ2_182D END AS OL_BDCLSAVGLMT_DLQ2_182D,
        CASE WHEN OL_BDCLSCNT_DLQ2_183D365D > 0 THEN OL_BDCLSSMLMT_DLQ2_183D365D / OL_BDCLSCNT_DLQ2_183D365D END AS OL_BDCLSAVGLMT_DLQ2_183D365D,
        CASE WHEN (NVL(OL_BDCLSCNT_DLQ2_182D, 0) + NVL(OL_BDCLSCNT_DLQ2_183D365D, 0)) > 0 THEN (NVL(OL_BDCLSSMLMT_DLQ2_182D, 0) + NVL(OL_BDCLSSMLMT_DLQ2_183D365D, 0)) / (NVL(OL_BDCLSCNT_DLQ2_182D, 0) + NVL(OL_BDCLSCNT_DLQ2_183D365D, 0)) END AS OL_BDCLSAVGLMT_DLQ2_365D,
        ------------------------------------------------------------------------
        CCOL_AVGLMT_EVER,
        CCOL_AVGLMT_30D,
        CCOL_AVGLMT_90D,
        CCOL_AVGLMT_91D365D,
        CCOL_AVGLMT_182D,
        CCOL_AVGLMT_183D365D,
        CASE WHEN CCOL_AVGLMT_182D IS NOT NULL AND CCOL_AVGLMT_183D365D IS NOT NULL THEN (CCOL_CNT_182D*CCOL_AVGLMT_182D + CCOL_CNT_183D365D*CCOL_AVGLMT_183D365D) / (CCOL_CNT_182D + OL_CNT_183D365D)
             WHEN CCOL_AVGLMT_182D IS NOT NULL AND CCOL_AVGLMT_183D365D IS NULL THEN CCOL_AVGLMT_182D
             ELSE CCOL_AVGLMT_183D365D
        END AS CCOL_AVGLMT_365D,
        ALL_SMTOB_2M3MWPS4P_EVER_N,--NEW--04.03.2025
        ALL_SMTOB_4M6MWPS4P_EVER_N,--NEW--04.03.2025
        ALL_SMTOB_7M12MWPS4P_EVER_N,--NEW--04.03.2025
        ALL_SMTOB_13M24MWPS4P_EVER_N--NEW--04.03.2025
FROM
MKR_LONGLIST_TMP6 K,
MKR_LONGLIST_TMP7 K7,
MKR_LONGLIST_TMP8 K8,
MKR_LONGLIST_TMP9 K9,
MKR_LONGLIST_TMP10 K10,
MKR_LONGLIST_TMP11 K11,
MKR_LONGLIST_TMP12 K12,
MKR_LONGLIST_OPNCNT L,
MKR_LONGLIST_OTHRCNT M
WHERE 1 = 1
AND K.ID = K7.ID
AND K.ID = K8.ID
AND K.ID = K9.ID
AND K.ID = K10.ID
AND K.ID = K11.ID
AND K.ID = K12.ID
AND K.ID = L.ID
AND K.ID = M.ID

),


